    RF_DATA = _pickle.loads(_zlib.decompress(_b64.b64decode(RF_B64)))
    RC_DATA = _pickle.loads(_zlib.decompress(_b64.b64decode(RC_B64)))
    _re_tuple = _pickle.loads(_zlib.decompress(_b64.b64decode(RE_B64)))
    RE_DATA, RI_DATA, RZ_DATA = _re_tuple
except Exception as e:
    RF_DATA = {}
    RC_DATA = {}
    RE_DATA = {}
    RI_DATA = {}
    RZ_DATA = {}
    print(f"failed to load reflection: {e}", file=sys.stderr)

def handle_reflection(opts):
    # Determine which reflection opt is active (last wins among rf/rc/re/rz/ri)
    # Find last occurrence in opt_order
    last = None
    last_val = None
    for o,v in opts.get('opt_order', []):
        if o in ('rf','rc','re','rz','ri'):
            last = o
            last_val = v
    if last is None:
        return (None, None)  # no reflection
    # Handle -H hiding: if hide_args, name is empty
    if opts.get('hide_args'):
        last_val = ""
    name = last_val if last_val is not None else ""
    lname = name.lower() if isinstance(name, str) else ""
    # For --rf, --rc, --re, --rz: on success RC 0, on fail RC 1 with Exception to stdout (not stderr)
    # For --ri: on success RC 0, on fail RC 1 with "Extension 'X' not present." to stdout
    if last == 'rf':
        # function names case-insensitive, but also handle leading backslash? e.g., \strlen?
        key = lname.lstrip("\\")
        if key in RF_DATA:
            out, rc = RF_DATA[key]
            return (out, 0)
        else:
            # Check for special: exit, die, clone? Those are in funcs but --rf for them?
            # From funcs list, clone, exit, die are included. Our capture should have them.
            return (f"Exception: Function {name}() does not exist\n", 1)
    elif last == 'rc':
        key = lname.lstrip("\\")
        if key in RC_DATA:
            out, rc = RC_DATA[key]
            return (out, 0)
        else:
            return (f'Exception: Class "{name}" does not exist\n', 1)
    elif last == 're':
        key = lname
        if key in RE_DATA:
            out, rc, err = RE_DATA[key]
            # RE output may be affected by INI? Like Current values? For -d changes, does --re show updated Current? Likely yes. For now, ignore and return captured (default). Handle -d for common?
            # TODO: update Current values based on INI?
            return (out, 0)
        else:
            return (f'Exception: Extension "{name}" does not exist\n', 1)
    elif last == 'rz':
        key = lname
        if key in RZ_DATA:
            out, rc = RZ_DATA[key]
            return (out, 0)
        else:
            return (f'Exception: Zend Extension "{name}" does not exist\n', 1)
    elif last == 'ri':
        key = lname
        if key in RI_DATA:
            out, rc, err = RI_DATA[key]
            # RI output affected by INI? Likely yes (shows Local/Master). For now return captured.
            return (out, 0)
        else:
            return (f"Extension '{name}' not present.\n", 1)
    return (None, None)

