def php_actual_type_name(v):
    if v is None:
        return "null"
    if isinstance(v, bool):
        return "bool"
    if isinstance(v, int):
        return "int"
    if isinstance(v, float):
        return "float"
    if isinstance(v, str):
        return "string"
    if isinstance(v, PHPArray):
        return "array"
    if isinstance(v, PHPObject):
        return f"{v.class_name} object"
    return "unknown"

